import { Bot, User, Download, Sparkles } from "lucide-react";
import ReactMarkdown from "react-markdown";

function FeedbackCard({ msg, onFeedback, feedbackPending, isLoadingChat }) {
  const suggestion = msg.suggestion || {};

  return (
    <div className="feedback-card">
      <div className="feedback-card-header">
        <Sparkles size={14} />
        <span>SUGGESTED ACTION — NEEDS YOUR APPROVAL</span>
      </div>

      <div className="feedback-card-title">
        {suggestion.title || msg.stepName || "Suggested Action"}
      </div>

      <div className="feedback-card-details">
        {suggestion.method && (
          <div className="feedback-card-row">
            <span className="feedback-card-label">Method:</span>
            <span className="feedback-card-value">{suggestion.method}</span>
          </div>
        )}
        {suggestion.target && (
          <div className="feedback-card-row">
            <span className="feedback-card-label">Target:</span>
            <span className="feedback-card-value">{suggestion.target}</span>
          </div>
        )}
        {suggestion.why && (
          <div className="feedback-card-row">
            <span className="feedback-card-label">Why:</span>
            <span className="feedback-card-value feedback-card-why">{suggestion.why}</span>
          </div>
        )}
      </div>

      {!msg.feedbackDone ? (
        <div className="feedback-card-actions">
          <button
            className="feedback-btn-accept"
            disabled={isLoadingChat || !feedbackPending}
            onClick={() => onFeedback(true)}
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="20 6 9 17 4 12"/>
            </svg>
            Accept
          </button>
          <button
            className="feedback-btn-reject"
            disabled={isLoadingChat || !feedbackPending}
            onClick={() => onFeedback(false)}
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <line x1="18" y1="6" x2="6" y2="18"/>
              <line x1="6" y1="6" x2="18" y2="18"/>
            </svg>
            Reject
          </button>
        </div>
      ) : (
        <div className={`feedback-card-done ${msg.feedbackChoice ? "done-accepted" : "done-rejected"}`}>
          {msg.feedbackChoice ? (
            <>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="20 6 9 17 4 12"/>
              </svg>
              Accepted
            </>
          ) : (
            <>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <line x1="18" y1="6" x2="6" y2="18"/>
                <line x1="6" y1="6" x2="18" y2="18"/>
              </svg>
              Rejected
            </>
          )}
        </div>
      )}
    </div>
  );
}

export default function ChatWindow({
  activeChat,
  chatEndRef,
  onFeedback,
  feedbackPending,
  isLoadingChat,
}) {
  return (
    <div className="chat">
      {activeChat?.messages.map((msg, index) => (
        <div
          key={index}
          className={`message-row ${msg.sender === "user" ? "row-user" : "row-bot"}`}
        >
          {msg.sender === "bot" && (
            <div className="avatar avatar-bot">
              <Bot size={16} />
            </div>
          )}

          <div className={`message ${msg.sender === "user" ? "message-user" : "message-bot"}`}>
            {msg.sender === "bot" ? (
              <ReactMarkdown
                components={{
                  p: ({ children }) => (
                    <p style={{ margin: "4px 0", whiteSpace: "pre-wrap" }}>{children}</p>
                  ),
                  ul: ({ children }) => (
                    <ul style={{ paddingLeft: "16px", margin: "4px 0" }}>{children}</ul>
                  ),
                  li: ({ children }) => <li style={{ margin: "2px 0" }}>{children}</li>,
                }}
              >
                {msg.text}
              </ReactMarkdown>
            ) : (
              <p style={{ whiteSpace: "pre-wrap" }}>{msg.text}</p>
            )}

            {msg.list && (
              <ul>
                {msg.list.map((item, i) => (
                  <li key={i}>{item}</li>
                ))}
              </ul>
            )}

            {(msg.awaitsFeedback || msg.feedbackDone) && (
              <FeedbackCard
                msg={msg}
                onFeedback={onFeedback}
                feedbackPending={feedbackPending}
                isLoadingChat={isLoadingChat}
              />
            )}

            <span className="msg-time">{msg.time}</span>
          </div>

          {msg.sender === "user" && (
            <div className="avatar avatar-user">
              <User size={16} />
            </div>
          )}
        </div>
      ))}
      <div ref={chatEndRef} />
    </div>
  );
}
